TLM.f("Sancti/11-21",{"officium":"In Presentatione Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","CredoDA","Prefatio=Maria=Presentatióne;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"Introitus":"Commune/C11","Lectio":"Commune/C11","Graduale":"Commune/C11","GradualeP":"Commune/C11","Tractus":"Commune/C11","Evangelium":"Commune/C11","Offertorium":"Commune/C11","Communio":"Commune/C11"},"sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Deus, qui beátam Maríam semper Vírginem, Spíritus Sancti habitáculum, hodiérna die in templo præsentári voluísti: præsta, quǽsumus; ut, ejus intercessióne, in templo glóriæ tuæ præsentári mereámur."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:14-16"},{"k":"text","la":"Ab inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 11:27-28"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"ref","la":"Luc 1:28 1:42"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"8f0eae79d2d2c5a4":{"t":"Sedulije, Ps 44, 2\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove! (Ps 44, 2) Iz srca mi navire radosna riječ, pripovijedam svoja djela Kralju!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sedulije) Zdravo, sveta Majko, koja si nam porodila Kralja koji vlada nebom i zemljom u vjekovječne vjekove!","kn":"Zdravo, sveta Majko, što nam porodi Kralja, koji vlada nebom i zemljom u vjekovječne vjekove! (Ps. 44, 2) Iz mog srca izvire divna pjesma: djela su moja namijenjena Kralju. Slava Ocu. Zdravo.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"e9688fb0cd88e422":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio da se na današnji dan blažena Marija vazda Djevica, prebivalište Duha Svetoga, prikaže u hramu, daj, molimo, da zavrijedimo biti po njezinu zagovoru prikazani u hramu tvoje slave.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si htio, da na današnji dan bude u hramu prikazana blažena Marija, vazda Djevica, prebivalište Duba Svetoga: podaj, molimo, da zavrijedimo po njezinom zagovoru biti prikazani u hramu slave Tvoje. Po Gospodinu... u jedinstvu istoga Duha Svetoga . . .","knRef":"Kniewald 1942, str. 782–783 (snimka 392) (OCR)"},"7ead540ba882eb49":{"t":"Sir 24, 14-16\nČitanje knjige Mudrosti. Bila sam stvorena od početka i prije vjekova i neću prestati do vječnosti. Služila sam pred njim u svetom stanu. I tako sam se utvrdila na Sionu i u svetom sam gradu počinula i u Jeruzalemu je sjedište moje vlasti. Ukorijenila sam se u časnom narodu koji ima udio svoje baštine u mojemu Bogu, a moj je boravak u zboru svetih.","kn":"Čitanje Knjige mudrosti (Crkv. 24, 14-16). Bila sam stvorena od početka i prije vijekova, i ne ću prestati do vječnosti. Služila sam pred njim u svetomu stanu. I tako sam se utvrdila na Sionu i u svetomu sam gradu počinula i u Jeruzalemu je sjedište moje vlasti. Ukorijenila sam se u časnom narodu, koji imade dio svoje baštine u mojemu Bogu, a moj je boravak u zboru svetih.","knRef":"Kniewald 1942, str. 836–837 (snimka 419) (OCR)"},"ba7f76728961f78c":{"t":"Blagoslovljena si i časna, Djevo Marijo, koja si bez povrede djevičanstva bila majka Spasiteljeva. Bogorodice Djevo, u tvojem se zatvori krilu i posta čovjek onaj koga sav svijet ne može obuhvatiti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nPoslije porođaja ostala si, Djevice, nepovrijeđena. Bogorodice, zagovaraj nas. <i>Aleluja</i>.","kn":", Blagcislovema si i časna. Djevo Marlj'O, koja se bez povrede čistoće nađe mati Spasiteljeva. Bogorodice Djevo u tvojem se, postavši čovj.ek, zatvori krilu, koga sav svijet ne obuhvata.\n\nAleluja, aleluja. I poslije poroda ostala si neozlijeđena. Djevice, Bogorodice, zagovaraj nas kod Boga, aleluja.","knRef":"Kniewald 1942, str. 700–701 (snimka 351) (OCR)"},"d34dc2adfd4e4049":{"t":"Lk 11, 27-28\nSlijedi sveto Evanđelje po Luki. U ono vrijeme: Kad je Isus govorio narodu, reče mu glasno neka žena iz naroda: Blago tijelu koje te je nosilo i prsima koja su te dojila. On na to odgovori: Još više blago onima koji slušaju Božju riječ i drže je.","kn":"t Slijedi sveto evanđelje po Luki (11, 27-28). U ono vrijeme, kad je Isus govorio narodu, reče mu glasno neka žena iz naroda: Blago tijelu, koje te je. nosilo i prsima, koja su te dojila. On na to Odgovori: Još više blago onima, koji slušaju Božju riječ i drže je.","knRef":"Kniewald 1942, str. 638–639 (snimka 320) (OCR)"},"9f99f01cc37689c1":{"t":"Lk 1, 28 i 42\nZdravo, Marijo, milosti puna, Gospodin s tobom, blagoslovljena ti među ženama i blagoslovljen plod utrobe tvoje.","kn":"(Lk. 1, 28). Zdravo Marijo, milosti puna, Gospodin s Tobom, blagoslovena Ti među ženama, blagosloven plod utrobe Tvoje.","knRef":"Kniewald 1942, str. 38–39 (snimka 20) (OCR)"},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Tvojom milostivošću. Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i' -sadašnju sreću i mir, po' G; n,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"cbd251d692a86320":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o prikazanju</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, da uvijek i, svagdje Tebi, Gospodine sveti. Oče svemogući, vječni Bože, zahvaljujemo i da Te hvalimo, slavimo i uzvisujemo o (Pohodu, Prikazanju, Bezgrješnom Začeću, Navještenju, Uznesenju. Rođenju, svetkovini) blažene Marije, vazda Djevice, koja je po Duhu Svetom začela jedinorođenoga Tvoga Sina i zadržavši slavu djevičanstva dala svijetu vječno svijetlo, Isuisa Krista, Gospodina našega, po kome anđeli hvale Tvoje veličanstvo, klanjaju Ti se gospodstva, podlažu Ti se vlasti, slave Te nebesa i nebeske sile s blaženim Serafinima kličući u zajedničkoj^ radosti. A mi Te molimo, da nam zapovjediš s njima sjediniti naše glasove smjerno ispovijedajući:","knRef":"Kniewald 1942, str. 22–23 (snimka 12) (OCR)"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca.","kn":"Blaženokrilo Djevice Marije, koje je nosilo Sina vječnoga Oca,","knRef":"Kniewald 1942, str. 838–839 (snimka 420) (OCR)"},"91ad6f2bf907ac82":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, okrepe našega spasenja, molimo te, da nas svuda štiti zagovor blažene Marije vazda Djevice kojoj smo na čast prinijeli ove žrtve tvojemu veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, okrepe našega spasenja, molimo, da nas zakrili zaištita blažene Marije, vazda Djevice, kojoj smo na počast ovo prinijeli Tvojem veličanstvu, po G. n.","knRef":"Kniewald 1942, str. 704–705 (snimka 353) (OCR)"}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
